BEGIN;
GRANT USAGE ON SCHEMA public,auth TO authenticated;
CREATE FUNCTION admin_assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF NOT coalesce(ok,false) THEN RAISE EXCEPTION 'FAIL: %',label; END IF; RAISE NOTICE 'PASS: %',label; END; $$;
CREATE FUNCTION admin_reject(command text,label text,expected text DEFAULT NULL) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE command; EXCEPTION WHEN OTHERS THEN IF expected IS NOT NULL AND SQLSTATE<>expected THEN RAISE EXCEPTION 'FAIL incorrect error % for %: %',SQLSTATE,label,SQLERRM;END IF;RAISE NOTICE 'PASS rejected: %',label;RETURN;END;RAISE EXCEPTION 'FAIL accepted: %',label;END; $$;
CREATE TEMP TABLE admin_actors(n integer,auth_id uuid,staff_id uuid,permission text);
INSERT INTO admin_actors SELECT n,('fa100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('fa110000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,(ARRAY['perm_finances_modifier_tarifs','perm_admin_categories','perm_admin_templates','perm_admin_parametres','perm_admin_produits_interdits','perm_clients_modifier_abonnement','perm_admin_utilisateurs',NULL,NULL])[n] FROM generate_series(1,9) n;
INSERT INTO auth.users(id,email) SELECT auth_id,'admin-test-'||n||'@example.test' FROM admin_actors;
INSERT INTO staff_users(id,auth_id,nom,email,role) SELECT staff_id,auth_id,'Admin test '||n,'admin-test-'||n||'@example.test',CASE WHEN n=8 THEN 'directeur' ELSE 'preparateur' END FROM admin_actors WHERE n<9;
INSERT INTO staff_permissions(staff_id) SELECT staff_id FROM admin_actors WHERE n<9;
DO $$ DECLARE a record; BEGIN FOR a IN SELECT * FROM admin_actors WHERE permission IS NOT NULL LOOP EXECUTE format('UPDATE staff_permissions SET %I=true WHERE staff_id=$1',a.permission) USING a.staff_id; END LOOP; END; $$;
INSERT INTO clients(id,user_id,nom,cp,type,abonnement) VALUES('fa200000-0000-4000-8000-000000000001','fa100000-0000-4000-8000-000000000009','Protected client','97400','particulier','freemium');
CREATE TEMP TABLE admin_baselines AS SELECT coalesce(jsonb_object_agg(destination_code,jsonb_build_object('base',base,'parKg',par_kg)),'{}') tariffs FROM tarifs WHERE actif;
GRANT SELECT ON admin_actors,admin_baselines TO authenticated;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.role','authenticated',true),set_config('request.jwt.claim.sub','fa100000-0000-4000-8000-000000000001',true);
SELECT admin_reject(format('SELECT save_admin_tariffs(%L::jsonb,%L::jsonb)',jsonb_set(tariffs,'{974,base}','-1'),tariffs),'invalid later destination rejects complete batch') FROM admin_baselines;
SELECT admin_reject(format('SELECT save_admin_tariffs(NULL,%L::jsonb)',tariffs),'null tariff payload rejected before write') FROM admin_baselines;
SELECT admin_assert(save_admin_tariffs(jsonb_set(tariffs,'{974,base}','40'),tariffs)->'974'->>'base'='40.00','isolated tariff permission saves batch') FROM admin_baselines;
SELECT admin_reject(format('SELECT save_admin_tariffs(%L::jsonb,%L::jsonb)',tariffs,tariffs),'stale tariff batch','40001') FROM admin_baselines;
SELECT admin_reject($q$SELECT save_admin_category(NULL,'{"label":"Forbidden","taux":{}}',NULL)$q$,'tariff permission does not grant categories','42501');
SELECT set_config('request.jwt.claim.sub','fa100000-0000-4000-8000-000000000002',true);
SELECT admin_reject($q$SELECT save_admin_category(NULL,'{"label":"Missing rates","taux":{"974":{"om":0}}}',NULL)$q$,'missing regional rate is not silently zero');
DO $$ DECLARE saved jsonb; original jsonb:='{"label":"Atomic category","codeHs":"1234","taux":{"974":{"om":0,"omr":0}}}'; BEGIN
 saved:=save_admin_category(NULL,original,NULL);
 PERFORM admin_assert((saved->'taux'->'974'->>'om')::numeric=0,'explicit zero rates accepted for isolated category permission');
 saved:=save_admin_category((saved->>'id')::uuid,jsonb_set(original,'{taux,974,om}','1.234'),original);
 PERFORM admin_assert((saved->'taux'->'974'->>'om')::numeric=1.23,'category returns canonical persisted rate for next CAS');
 original:=saved-'id';
 PERFORM admin_reject(format('SELECT save_admin_category(%L,%L,%L)',saved->>'id',jsonb_set(original,'{taux,974,om}','101'),original),'invalid rate rolls back label and all rates');
 saved:=save_admin_category((saved->>'id')::uuid,jsonb_set(original,'{label}','"Changed category"'),original);
 PERFORM admin_reject(format('SELECT save_admin_category(%L,%L,%L)',saved->>'id',original,original),'stale category draft rejected','40001');
 PERFORM admin_reject(format('SELECT delete_admin_category(%L,%L)',saved->>'id',original),'stale category deletion rejected','40001');
 PERFORM delete_admin_category((saved->>'id')::uuid,saved-'id');
 PERFORM admin_assert(true,'isolated category permission deletes unused category explicitly');
END; $$;
SELECT set_config('request.jwt.claim.sub','fa100000-0000-4000-8000-000000000003',true);
SELECT admin_assert(save_message_template('admin_test','email','Saved body',NULL)='Saved body','isolated template permission saves');
SELECT admin_reject($q$SELECT save_message_template('admin_test','email','Overwrite',NULL)$q$,'stale template rejected','40001');
SELECT admin_reject($q$SELECT save_message_template(NULL,'email','Body',NULL)$q$,'null template rejected');
SELECT admin_reject($q$SELECT save_message_template('admin_test',NULL,'Body',NULL)$q$,'null channel rejected');
SELECT admin_reject($q$SELECT save_admin_setting('business','{}',NULL)$q$,'template permission cannot edit business','42501');
SELECT set_config('request.jwt.claim.sub','fa100000-0000-4000-8000-000000000004',true);
SELECT admin_reject($q$SELECT save_admin_setting(NULL,'{}',NULL)$q$,'null setting key rejected','42501');
SELECT admin_reject($q$SELECT save_admin_setting('secrets','{}',NULL)$q$,'other setting key rejected','42501');
RESET ROLE;
DELETE FROM app_settings WHERE key='business';
SET LOCAL ROLE authenticated;
SELECT admin_assert(save_admin_setting('business','{"fraisStockage":1,"stockageGratuit":7,"diviseurVolumetrique":5000,"relancesFeuVert":"J+2, J+5","relancesPaiement":"J+5"}',NULL)->>'stockageGratuit'='7','isolated business permission saves rules');
SELECT admin_reject($q$SELECT save_admin_setting('business','{}',NULL)$q$,'stale business update rejected','40001');
SELECT set_config('request.jwt.claim.sub','fa100000-0000-4000-8000-000000000005',true);
RESET ROLE;
DELETE FROM app_settings WHERE key='produits_interdits';
SET LOCAL ROLE authenticated;
SELECT admin_assert(save_admin_setting('produits_interdits','["Aérosols — transport interdit"]',NULL)= '["Aérosols — transport interdit"]','isolated forbidden-products permission saves');
SELECT admin_reject($q$SELECT save_admin_setting('produits_interdits','[5]','["Aérosols — transport interdit"]')$q$,'invalid product list rejected');
SELECT set_config('request.jwt.claim.sub','fa100000-0000-4000-8000-000000000006',true);
SELECT admin_assert(NOT has_permission('perm_clients_modifier'),'subscription-only actor has no client edit permission');
SELECT admin_assert(save_client_subscription('fa200000-0000-4000-8000-000000000001','{"abonnement":"premium_annuel","abonnementDebut":"2026-09-17","abonnementFin":"2027-09-17"}','{"abonnement":"freemium","abonnementDebut":null,"abonnementFin":null}')->>'abonnement'='premium_annuel','subscription-only actor can save subscription atomically');
SELECT admin_reject($q$SELECT save_client_subscription('fa200000-0000-4000-8000-000000000001',NULL,NULL)$q$,'null subscription draft rejected');
SELECT admin_reject($q$SELECT save_client_subscription('fa200000-0000-4000-8000-000000000001','{"abonnement":"vip"}','{"abonnement":"freemium","abonnementDebut":null,"abonnementFin":null}')$q$,'stale subscription rejected','40001');
SELECT set_config('request.jwt.claim.sub','fa100000-0000-4000-8000-000000000007',true);
SELECT admin_reject($q$SELECT set_staff_active('fa110000-0000-4000-8000-000000000001',false,true)$q$,'delegated users permission is not direction','42501');
SELECT set_config('request.jwt.claim.sub','fa100000-0000-4000-8000-000000000008',true);
SELECT admin_reject($q$SELECT set_staff_active('fa110000-0000-4000-8000-000000000008',false,true)$q$,'self suspension rejected');
SELECT admin_assert(set_staff_active('fa110000-0000-4000-8000-000000000001',false,true)->>'active'='false','direction suspends access without deleting history');
SELECT admin_reject($q$SELECT set_staff_active('fa110000-0000-4000-8000-000000000001',true,true)$q$,'stale activation rejected','40001');
SELECT admin_assert(set_staff_active('fa110000-0000-4000-8000-000000000001',true,false)->>'active'='true','reactivation requires explicit direction command');
SELECT set_config('request.jwt.claim.sub','fa100000-0000-4000-8000-000000000009',true);
SELECT admin_reject($q$SELECT save_admin_tariffs('{}','{}')$q$,'client cannot change tariffs','42501');
SELECT admin_reject($q$SELECT save_message_template('admin_test','email','Body','Saved body')$q$,'client cannot change templates','42501');
RESET ROLE;
SELECT admin_assert((SELECT nom='Protected client' AND email IS NULL FROM clients WHERE id='fa200000-0000-4000-8000-000000000001'),'subscription command preserves other client fields');
SELECT admin_assert((SELECT count(*)=1 FROM audit_actions WHERE action='admin_tariffs_saved' AND user_id='fa100000-0000-4000-8000-000000000001'),'only successful tariff command is audited');
SELECT admin_assert((SELECT count(*)=1 FROM tarifs WHERE destination_code='974' AND actif AND base=40),'failed and stale batches do not alter active tariff');
SELECT admin_assert((SELECT count(*)=3 FROM audit_actions WHERE action='admin_category_saved' AND user_id='fa100000-0000-4000-8000-000000000002'),'category failure produces no partial audit or write');
SELECT admin_assert(NOT has_function_privilege('anon','save_admin_tariffs(jsonb,jsonb)','EXECUTE') AND NOT has_function_privilege('anon','save_client_subscription(uuid,jsonb,jsonb)','EXECUTE'),'admin commands denied to anonymous role');
INSERT INTO colis(client_id,statut) VALUES('fa200000-0000-4000-8000-000000000001','annule');
SELECT admin_reject($q$DELETE FROM clients WHERE id='fa200000-0000-4000-8000-000000000001'$q$,'client deletion cannot cascade even cancelled history');
SELECT admin_assert((SELECT count(*)=1 FROM clients WHERE id='fa200000-0000-4000-8000-000000000001'),'client history deletion rejection preserves client');
INSERT INTO auth.users(id,email) VALUES('fa100000-0000-4000-8000-000000000010','legacy-director@example.test');
UPDATE profiles SET role='directeur' WHERE id='fa100000-0000-4000-8000-000000000010';
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','fa100000-0000-4000-8000-000000000010',true);
SELECT admin_reject($q$SELECT set_staff_active('fa110000-0000-4000-8000-000000000008',false,true)$q$,'last active directory account cannot be suspended by legacy director profile');
RESET ROLE;
UPDATE profiles SET actif=false WHERE id IN ('fa100000-0000-4000-8000-000000000001','fa100000-0000-4000-8000-000000000008');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','fa100000-0000-4000-8000-000000000001',true);
SELECT admin_reject($q$SELECT save_admin_tariffs('{}','{}')$q$,'inactive profile cannot use retained tariff permission','42501');
SELECT set_config('request.jwt.claim.sub','fa100000-0000-4000-8000-000000000008',true);
SELECT admin_reject($q$SELECT set_staff_active('fa110000-0000-4000-8000-000000000001',true,true)$q$,'inactive director cannot reactivate staff','42501');
SELECT set_config('request.jwt.claim.sub','fa100000-0000-4000-8000-000000000009',true);
SELECT admin_assert((SELECT count(*)=0 FROM client_outgoing_tracking(NULL)),'null tracking scope returns no dossier');
RESET ROLE;
ROLLBACK;
